export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" } }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: bridgeElement.bridgeAttribute("description")
    })
  }

import { Controller } from "@hotwired/stimulus"
import { onNextEventLoopTick } from "helpers/timing_helpers"

export default class extends Controller {
  static targets = [ "unread" ]
  static classes = [ "unread" ]

  connect() {
    onNextEventLoopTick(() => this.update())
  }

  update() {
    onNextEventLoopTick(() => {
      if (this.#available) {
        const unreadCount = this.#unreadCount

        if (unreadCount > 0) {
          navigator.setAppBadge(unreadCount)
        } else {
          navigator.clearAppBadge()
        }
      }
    })
  }

  clear() {
    onNextEventLoopTick(() => {
      if (this.#available) {
        navigator.clearAppBadge()
      }
    })
  }

  get #unreadCount() {
    return this.unreadTargets.filter(unreadTarget => unreadTarget.classList.contains(this.unreadClass)).length
  }

  get #available() {
    return "setAppBadge" in navigator
  }
}
"
}

