export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// The server sends raw timestamps and the browser turns them into words, so the
// same HTML can be cached and shared between people in different timezones. Words
// are written in the timezone the server rendered with (the `timezone` meta tag)
// so they stay consistent with server-side day grouping, even when the browser's
// resolved timezone differs in a PWA.

const TIME_FORMAT = { hour: "numeric", minute: "2-digit" }
const DATE_FORMAT = { month: "short", day: "numeric" }
const DATE_WITH_YEAR_FORMAT = { month: "short", day: "numeric", year: "numeric" }
const WEEKDAY_DATE_FORMAT = { weekday: "long", month: "long", day: "numeric" }
const DAY_PARTS_FORMAT = { year: "numeric", month: "2-digit", day: "2-digit" }

const DAYS_IN_WEEK = 7
const DAYS_IN_MONTH = 30
const DAYS_IN_YEAR = 365

export function formatTimestamp(date, format) {
  switch (format) {
    case "time":         return formatter(TIME_FORMAT).format(date)
    case "date":         return formatDate(date)
    case "dateWithYear": return formatter(DATE_WITH_YEAR_FORMAT).format(date)
    case "datetime":     return `${formatDate(date)}, ${formatter(TIME_FORMAT).format(date)}`
    case "weekdayDate":  return formatter(WEEKDAY_DATE_FORMAT).format(date)
    case "relative":     return formatRelativeDate(date)
    default:             return formatDate(date)
  }
}

// Calendar dates ("2026-09-06") arrive as plain dates, not moments in time, so
// they're formatted from their local parts without an explicit timezone to
// render the exact day the server intended.
export function formatCalendarDate(date, format = "weekdayDate") {
  const options = format === "date" ? DATE_WITH_YEAR_FORMAT : WEEKDAY_DATE_FORMAT
  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function formatDate(date) {
  const options = yearInTimezone(date) === yearInTimezone(new Date()) ? DATE_FORMAT : DATE_WITH_YEAR_FORMAT
  return formatter(options).format(date)
}

function formatRelativeDate(date) {
  const now = new Date()
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return date <= now ? formatter(TIME_FORMAT).format(date) : relativeTimeFormatter().format(0, "day")
  } else if (days < 0) {
    return days > -DAYS_IN_WEEK ? relativeTimeFormatter().format(days, "day") : formatDate(date)
  } else if (days < DAYS_IN_WEEK) {
    return relativeTimeFormatter().format(days, "day")
  } else if (days < DAYS_IN_MONTH) {
    return relativeTimeFormatter().format(Math.round(days / DAYS_IN_WEEK), "week")
  } else if (days < DAYS_IN_YEAR) {
    return relativeTimeFormatter().format(Math.round(days / DAYS_IN_MONTH), "month")
  } else {
    return relativeTimeFormatter().format(Math.round(days / DAYS_IN_YEAR), "year")
  }
}

function yearInTimezone(date) {
  return datePartsInTimezone(date).year
}

// Snap a timestamp to midnight using the timezone the server rendered with (the
// `timezone` meta tag), so client day boundaries match the server's instead of
// following the browser's resolved timezone, which can differ in a PWA.
function datePartsInTimezone(date) {
  return formatter(DAY_PARTS_FORMAT).formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

const formatters = new Map()

function formatter(options) {
  const timezone = getMetaContent("timezone")
  const key = JSON.stringify([ options, timezone || null ])

  if (!formatters.has(key)) {
    formatters.set(key, buildFormatter(options, timezone))
  }

  return formatters.get(key)
}

function buildFormatter(options, timezone) {
  try {
    return new Intl.DateTimeFormat("en-US", { ...options, timeZone: timezone })
  } catch {
    return new Intl.DateTimeFormat("en-US", options)
  }
}

let cachedRelativeTimeFormatter

function relativeTimeFormatter() {
  cachedRelativeTimeFormatter ||= new Intl.RelativeTimeFormat("en", { numeric: "auto" })
  return cachedRelativeTimeFormatter
}
